    show(visible){const changed=visible!==local.shown;local.shown=visible;
      if(visible&&changed&&local.id)refresh().catch(error=>notify(friendly(error),'error'));},
    updateBusy(){renderCurrent();}
  };
}

// MIT — Reports contain retained source material and the analyst's own work.
import {hasOriginalFiles,reportSourceRecord,originalFilesMarkdown,originalFilesHtml} from './source-file-reports.mjs';
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const md = value => String(value ?? '').replace(/[\\\x60*_{}\[\]<>#+!|]/g, '\\$&');
const rendered = value => typeof value === 'string' ? value : JSON.stringify(value, null, 2);
const url = value => { try { const parsed = new URL(value); return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : ''; } catch { return ''; } };
const link = (label, target) => { const href = url(target); return href ? '<a href="' + escape(href) + '" rel="noreferrer">' + escape(label) + '</a>' : escape(label); };
const occurrenceRecords = source => source.citations.map(citation => ({
  occurrenceId: citation.occurrenceId, editionId: citation.editionId,
  questionId: citation.questionId, key: citation.key,
  original: reportSourceRecord(citation.original,source.variants.find(variant=>variant.contentDigest===citation.contentDigest)?.content),
}));
function includedSources(view) {
  const references = new Set(view.findings.flatMap(finding => finding.sourceIds));
  return view.sources.filter(source => source.selected || references.has(source.id));
}
function analystNotes(view) {
  const unique = new Map();
  for (const selection of view.unavailableSelections ?? []) {
    if (!selection.note && !selection.selected) continue;
    const key = selection.questionId + '\n' + selection.editionId + '\n' + selection.note;
    if (!unique.has(key)) unique.set(key, selection);
  }
  return [...unique.values()];
}
function fence(value) {
  const content = rendered(value);
  let width = 3;
  for (const run of content.matchAll(/\x60+/g)) width = Math.max(width, run[0].length + 1);
  const marker = '\x60'.repeat(width);
  return marker + (typeof value === 'string' ? 'text' : 'json') + '\n' + content + '\n' + marker;
}


function citationReviewMarkdown(view){
  if(!(view.citationUpdates?.length||view.citationReviews?.length))return [];
  const lines=['## Citation update review','',
    'These notices are linked to the DOI records retained in this dossier. Each disposition records the reviewer and the exact report revisions.','',
    '| Notice | Updated work | Type | Review |','| --- | --- | --- | --- |'];
  for(const notice of view.citationUpdates??[])
    lines.push('| '+[notice.noticeDoi,notice.targetDoi,notice.type,notice.status].map(md).join(' | ')+' |');
  for(const review of view.citationReviews??[]){
    lines.push('','### '+md(review.notice.title),'',md(review.notice.noticeDoi)+' updates '+md(review.notice.targetDoi)+'.','',
      'Reviewer: '+md(review.actor)+' · '+md(review.createdAt)+' · Decision: '+md(review.decision),'',
      'Original report revision '+review.originalRevision+' → reviewed report revision '+review.revision+'.','',
      review.reason,'','Source edition: '+md(review.notice.latestSource.editionId)+
        ' · Retained edition SHA-256: '+md(review.notice.latestSource.sourceSha256),'',
      '#### Original notice and capture bindings','',fence(review.notice),'');
    for(const disposition of review.findingDispositions)
      lines.push('- Finding '+md(disposition.findingId)+': '+md(disposition.disposition)+'. '+md(disposition.reason),'');
    for(const change of review.changes.evidence)
      lines.push('Evidence '+md(change.occurrenceId)+':','',fence({before:change.before,after:change.after}),'');
    for(const change of review.changes.findings)
      lines.push('Finding '+md(change.findingId)+':','',
        '**Previous finding: '+md(change.before.title)+'**','',change.before.text,'','Citations: '+change.before.occurrenceIds.map(md).join(', '),'',
        '**Reviewed finding: '+md(change.after.title)+'**','',change.after.text,'','Citations: '+change.after.occurrenceIds.map(md).join(', '),'');
  }
  lines.push('','### Retained update acquisition coverage','');
  for(const item of view.citationCoverage??[])lines.push('- '+md(item.label)+': '+md(item.coverage)+
    '; updates '+md(item.updatesLookup)+(item.issues.length?'; '+item.issues.map(md).join(', '):'')+'.','');
  return lines;
}
function citationReviewHtml(view){
  if(!(view.citationUpdates?.length||view.citationReviews?.length))return '';
  const notices=(view.citationUpdates??[]).map(value=>'<tr><td>'+link(value.noticeDoi,'https://doi.org/'+encodeURIComponent(value.noticeDoi))+
    '</td><td>'+link(value.targetDoi,'https://doi.org/'+encodeURIComponent(value.targetDoi))+'</td><td>'+escape(value.type)+
    '</td><td>'+escape(value.status)+'</td></tr>').join('');
  const reviews=(view.citationReviews??[]).map(review=>'<article><h3>'+escape(review.notice.title)+'</h3>'+
    '<p>'+escape(review.notice.noticeDoi)+' updates '+escape(review.notice.targetDoi)+'</p>'+
    '<p class="muted">Reviewer: '+escape(review.actor)+' · '+escape(review.createdAt)+' · '+escape(review.decision)+'</p>'+
    '<p>Original report revision '+review.originalRevision+' → reviewed report revision '+review.revision+'</p>'+
    '<div class="prose">'+escape(review.reason)+'</div>'+
    '<p class="file-identity">Source edition: '+escape(review.notice.latestSource.editionId)+
    ' · Retained edition SHA-256: '+escape(review.notice.latestSource.sourceSha256)+'</p>'+
    review.findingDispositions.map(value=>'<p><strong>'+escape(value.findingId)+': '+escape(value.disposition)+
      '</strong></p><div class="prose">'+escape(value.reason)+'</div>').join('')+
    review.changes.findings.map(change=>'<details open><summary>Finding '+escape(change.findingId)+'</summary>'+
      '<h4>Previous finding: '+escape(change.before.title)+'</h4><div class="prose">'+escape(change.before.text)+'</div><p class="file-identity">'+escape(change.before.occurrenceIds.join(', '))+'</p>'+
      '<h4>Reviewed finding: '+escape(change.after.title)+'</h4><div class="prose">'+escape(change.after.text)+'</div><p class="file-identity">'+escape(change.after.occurrenceIds.join(', '))+'</p></details>').join('')+
    (review.changes.evidence.length?'<details><summary>Evidence changes</summary><pre>'+escape(JSON.stringify(review.changes.evidence,null,2))+'</pre></details>':'')+
    '<details><summary>Original notice and response bindings</summary><pre>'+escape(JSON.stringify(review.notice,null,2))+'</pre></details></article>').join('');
  const coverage=(view.citationCoverage??[]).map(value=>'<li>'+escape(value.label)+': '+escape(value.coverage)+
    '; updates '+escape(value.updatesLookup)+(value.issues.length?'; '+escape(value.issues.join(', ')):'')+'</li>').join('');
  return '<section><h2>Citation update review</h2><p>These notices are linked to the DOI records retained in this dossier. Each disposition keeps its reviewer and original report revisions.</p>'+
    '<div class="table"><table><thead><tr><th>Notice</th><th>Updated work</th><th>Type</th><th>Review</th></tr></thead><tbody>'+notices+
    '</tbody></table></div>'+reviews+'<details><summary>Retained update acquisition coverage</summary><ul>'+coverage+'</ul></details></section>';
}

export function markdownReport(view) {
  const sources = includedSources(view), numbering = new Map(sources.map((source, index) => [source.id, index + 1]));
  const lines = ['# ' + md(view.title), '', view.description, '',
    'Revision ' + view.revision + ' · ' + view.updatedAt, '', '## Research questions', ''];
  for (const question of view.questions) {
    lines.push('### ' + md(question.text), '', 'Status: ' + question.status, '');
    if (question.notes) lines.push(question.notes, '');
    for (const finding of view.findings.filter(row => row.questionId === question.id)) {
      const references = finding.sourceIds.map(id => numbering.get(id)).filter(Boolean).map(number => '[' + number + ']').join(' ');
      lines.push('#### ' + md(finding.title), '', finding.text, '', references, '');
      if (finding.unavailableSources) lines.push('Original edition references: ' + finding.occurrenceIds.join(', '), '');
    }
  }
  lines.push('## Selected sources', '');
  if (!sources.length) lines.push('No retained sources selected for this report.', '');
  for (const [index, source] of sources.entries()) {
    lines.push('### [' + (index + 1) + '] ' + md(source.title), '');
    if (url(source.url)) lines.push('<' + url(source.url).replace(/>/g, '%3E') + '>', '');
    if (source.authors.length) lines.push('Authors: ' + source.authors.map(md).join('; '), '');
    lines.push('Provider: ' + md(source.provider) + (source.publishedAt ? ' · Published: ' + md(source.publishedAt) : ''), '');
    lines.push('Assessment: ' + source.classification, '');
    if (source.note) lines.push(source.note, '');
    for (const variant of source.variants) {
      lines.push('Edition ' + variant.editionId, '', originalFilesMarkdown(variant.content) ?? fence(variant.content), '');
    }
    lines.push('Original occurrences: ' + source.citations.map(citation => citation.editionId + '/' + citation.key).join(', '), '');
    lines.push(source.variants.some(variant=>hasOriginalFiles(variant.content)) ? 'Source records and original-file references:' : 'Original source records:', '', fence(occurrenceRecords(source)), '');
  }
  const notes = analystNotes(view);
  if (notes.length) {
    lines.push('## Notes attached to original edition references', '');
    for (const note of notes) lines.push('- ' + md(note.editionId + '/' + note.key) + ' · ' + note.classification +
      (note.note ? '\n\n' + note.note : ''), '');
  }
  lines.push(...citationReviewMarkdown(view));
  lines.push('## Editions and source usage', '',
    '| Edition | Provider | Storage | Status | Source observations |',
    '| --- | --- | --- | --- | --- |');
  for (const edition of view.editions) lines.push('| ' + [edition.label, edition.provider, edition.mode,
    edition.status, JSON.stringify(edition.usage)].map(value => md(value).replace(/\n/g, ' ')).join(' | ') + ' |');
  lines.push('', '## Source terms and original operation references', '');
  for (const edition of view.editions) {
    lines.push('- ' + md(edition.label) + ': ' + md(edition.sourceTerms ?? 'Original edition access') +
      (edition.sourceReference ? ' · ' + md(edition.sourceReference) : ''), '');
    if (edition.reference) lines.push(fence(edition.reference), '');
    if (edition.origin) lines.push(fence(edition.origin), '');
  }
  return lines.join('\n') + '\n';
}

export function htmlReport(view) {
  const sources = includedSources(view), numbers = new Map(sources.map((source, index) => [source.id, index + 1]));
  const questions = view.questions.map(question => '<section><h2>' + escape(question.text) +
    '</h2><p class="muted">Status: ' + escape(question.status) + '</p>' +
    (question.notes ? '<div class="prose">' + escape(question.notes) + '</div>' : '') +
    view.findings.filter(row => row.questionId === question.id).map(finding =>
      '<article><h3>' + escape(finding.title) + '</h3><div class="prose">' + escape(finding.text) +
      '</div><p>' + finding.sourceIds.filter(id => numbers.has(id)).map(id =>
        '<a href="#source-' + numbers.get(id) + '">[' + numbers.get(id) + ']</a>').join(' ') + '</p>' +
      (finding.unavailableSources ? '<details><summary>Original edition references</summary><pre>' +
        escape(finding.occurrenceIds.join('\n')) + '</pre></details>' : '') + '</article>').join('') + '</section>').join('');
  const sourceHtml = sources.map((source, index) => '<article id="source-' + (index + 1) + '"><h3>[' +
    (index + 1) + '] ' + link(source.title, source.url) + '</h3><p class="muted">' +
    escape([source.provider, source.publishedAt, source.authors.join('; ')].filter(Boolean).join(' · ')) +
    '</p><p>Assessment: ' + escape(source.classification) + '</p>' +
    (source.note ? '<div class="prose">' + escape(source.note) + '</div>' : '') +
    source.variants.map(variant => '<details open><summary>Edition ' + escape(variant.editionId) +
      '</summary>' + (originalFilesHtml(variant.content) ?? '<pre>' + escape(rendered(variant.content)) + '</pre>') + '</details>').join('') +
    '<details><summary>' + (source.variants.some(variant=>hasOriginalFiles(variant.content)) ? 'Source records and original-file references' : 'Original source records') + '</summary><pre>' +
    escape(JSON.stringify(occurrenceRecords(source), null, 2)) + '</pre></details></article>').join('');
  const notes = analystNotes(view).map(note => '<article><h3>' + escape(note.editionId + '/' + note.key) +
    '</h3><p>' + escape(note.classification) + '</p><div class="prose">' + escape(note.note) + '</div></article>').join('');
  const editions = view.editions.map(edition => '<tr><td>' + escape(edition.label) + '</td><td>' +
    escape(edition.provider) + '</td><td>' + escape(edition.mode) + '</td><td>' + escape(edition.status) +
    '</td><td><pre>' + escape(JSON.stringify(edition.usage, null, 2)) + '</pre></td></tr>').join('');
  const origins = view.editions.map(edition => '<details><summary>' + escape(edition.label) +
    '</summary><p>' + escape(edition.sourceTerms ?? 'Original edition access') + '</p>' +
    (edition.sourceReference ? '<p>' + link(edition.sourceReference, edition.sourceReference) + '</p>' : '') +
    '<pre>' + escape(JSON.stringify(edition.reference ?? edition.origin ?? {}, null, 2)) + '</pre></details>').join('');
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; base-uri \'none\'; form-action \'none\'">' +
    '<title>' + escape(view.title) + '</title><style>' +
    '*{box-sizing:border-box}body{margin:0;background:#f5f5f4;color:#202020;font:15px/1.6 system-ui,sans-serif}' +
    'main{max-width:1060px;margin:0 auto;padding:48px 32px 80px;background:#fff}h1{font-size:32px;line-height:1.2}h2{font-size:22px;margin-top:40px}' +
    'h3{font-size:17px}section,article{break-inside:avoid}article{border-top:1px solid #d5d5d2;padding:18px 0}.muted{color:#62625e}' +
    '.prose{white-space:pre-wrap;overflow-wrap:anywhere;margin:12px 0}a{color:#202020;text-underline-offset:3px}' +
    'pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace;background:#f3f3f0;padding:12px;border:1px solid #deded8}' +
    'table{border-collapse:collapse;width:100%}th,td{text-align:left;border:1px solid #d5d5d2;padding:8px;vertical-align:top}td pre{margin:0;padding:0;border:0;background:none}' +
    '.source-file{padding:10px 12px;border:1px solid #ddd}.source-file summary{overflow-wrap:anywhere}.file-identity{font-size:12px;overflow-wrap:anywhere}' +
    'figure{margin:16px 0}figure img{display:block;max-width:100%;height:auto}figcaption{font-size:12px;color:#62625e}.file-text pre{max-height:36rem;overflow:auto}' +
    'details{margin:10px 0}summary{cursor:pointer}.table{overflow-x:auto}footer{margin-top:40px;border-top:1px solid #ddd;padding-top:16px;font-size:12px}' +
    '@media(max-width:600px){main{padding:24px 16px}h1{font-size:26px}}@media print{body{background:#fff}main{max-width:none;padding:0}a{text-decoration:none}details{break-inside:avoid}}' +
    '</style></head><body><main><header><p class="muted">RESEARCH DOSSIER</p><h1>' + escape(view.title) +
    '</h1><div class="prose">' + escape(view.description) + '</div><p class="muted">Revision ' + view.revision +
    ' · ' + escape(view.updatedAt) + '</p></header>' + questions + '<section><h2>Selected sources</h2>' +
    (sourceHtml || '<p>No retained sources selected for this report.</p>') + '</section>' +
    (notes ? '<section><h2>Notes attached to original edition references</h2>' + notes + '</section>' : '') +
    citationReviewHtml(view) +
    '<section><h2>Editions and source usage</h2><div class="table"><table><thead><tr><th>Edition</th><th>Provider</th><th>Storage</th><th>Status</th><th>Source observations</th></tr></thead><tbody>' +
    editions + '</tbody></table></div></section><section><h2>Source terms and original operations</h2>' + origins +
    '</section><footer>' + escape(view.id) + ' · Revision ' + view.revision +
    ' · Portable JSON preserves retained source bytes and the complete project history.</footer></main></body></html>\n';
}

// MIT. Private research dossier operator over the maintained dossier engine.
import { createServer } from 'node:http';
import { pipeline } from 'node:stream/promises';
import { readFile } from 'node:fs/promises';
import { dirname, isAbsolute, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { randomBytes, randomUUID, timingSafeEqual } from 'node:crypto';
import {privateDirectory,writeJson,digest,jsonBytes as canonicalBytes} from '../node/store.mjs';
import {RESEARCH_WORKSPACE_API,RESEARCH_WORKSPACE_CONNECTION,researchWorkspaceId,researchSummary,researchPage,researchSection,researchComparison,researchCrossrefReview} from './workspace-protocol.mjs';
import { openDossierStore } from './dossier.mjs';
import {inspectResearchResponse,inspectRetainedSource,readRetainedSourceFile} from './source-inspection.mjs';
import { openClinicalTrialsWorkspace } from './clinical-trials-workspace.mjs';
import { handleClinicalTrialsRoute } from './clinical-trials-routes.mjs';
import { receiveOpenAlexEdition } from './openalex.mjs';
import { openSavedOpenAlexWorkspace } from './openalex-workspace.mjs';
import { openUnstructuredWorkspace, openSavedDocumentBuyerSource } from './unstructured-workspace.mjs';
import { openUnstructuredPipelineWorkspace, openSavedPipelineSource, PIPELINE_UPLOAD_BODY_BYTES } from './unstructured-pipelines-workspace.mjs';

import {openResearchObjectSource} from './object-inputs.mjs';

const PUBLIC = fileURLToPath(new URL('./public/', import.meta.url));
const TYPES = Object.freeze({
  'index.html': 'text/html; charset=utf-8',
  'app.js': 'text/javascript; charset=utf-8',
  'style.css': 'text/css; charset=utf-8',
  'crossref.js': 'text/javascript; charset=utf-8',
  'unstructured.js': 'text/javascript; charset=utf-8',
  'unstructured.css': 'text/css; charset=utf-8',
  'object-inputs.js': 'text/javascript; charset=utf-8',
  'unstructured-pipelines.js': 'text/javascript; charset=utf-8',
  'unstructured-pipelines.css': 'text/css; charset=utf-8',
  'clinical-trials.js': 'text/javascript; charset=utf-8',
  'clinical-trials.css': 'text/css; charset=utf-8',
  'source-bundles.js': 'text/javascript; charset=utf-8',
  'source-inspection.js': 'text/javascript; charset=utf-8',
  'citation-review.js': 'text/javascript; charset=utf-8',
  'citation-review.css': 'text/css; charset=utf-8',
  'source-bundles.css': 'text/css; charset=utf-8',
});
const MAX_SOURCE_BUNDLE_BODY = 128 * 1024 * 1024 + 65536; // A 64 MiB bundle inside the rawText JSON string.
const MAX_RESEARCH_BODY = 96 * 1024 * 1024 + 65536; // 16 MiB raw UTF-8, worst-case JSON escaping plus envelope.
const MAX_PORTABLE_BODY = 256 * 1024 * 1024 + 65536; // Engine caps the serialized portable record at 256 MiB.
const MAX_CONTROL_BODY = 1024 * 1024;
const MAX_CITATION_REVIEW_BODY = 16 * 1024 * 1024;
const jsonBytes = value => Buffer.from(JSON.stringify(value) + '\n');
const fail = code => { throw Object.assign(new Error(code), {code}); };
const requireValue = (condition, code) => { if (!condition) fail(code); };
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const safeCode = error => typeof error?.code === 'string' && /^[A-Z0-9_]{1,100}$/.test(error.code) ? error.code : 'DOSSIER_OPERATION_FAILED';

async function readJson(req, limit) {
  const type = (req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
  requireValue(type === 'application/json', 'JSON_BODY_REQUIRED');
  const declared = req.headers['content-length'];
  if (declared !== undefined) {
    requireValue(/^[0-9]+$/.test(declared), 'CONTENT_LENGTH_INVALID');
    requireValue(Number(declared) <= limit, 'UPLOAD_SIZE_LIMIT');
  }
  const chunks = []; let length = 0;
  for await (const chunk of req) {
    length += chunk.length;
    requireValue(length <= limit, 'UPLOAD_SIZE_LIMIT');
    chunks.push(chunk);
  }
  let value;
  try { value = JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(Buffer.concat(chunks))); }
  catch { fail('JSON_INVALID'); }
  requireValue(plain(value), 'JSON_OBJECT_REQUIRED');
  return value;
}
function revision(value) {
  requireValue(Number.isSafeInteger(value) && value >= 0, 'EXPECTED_REVISION_REQUIRED');
  return value;
}
function selectedFields(value, keys) {
  const result = {};
  for (const key of keys) if (Object.hasOwn(value, key)) result[key] = value[key];
  return result;
}
function pathId(value) {
  let decoded;
  try { decoded = decodeURIComponent(value); } catch { fail('DOSSIER_ID_INVALID'); }
  requireValue(typeof decoded === 'string' && decoded.length > 0 && decoded.length <= 160 &&
    !/[\u0000-\u001f\u007f/\\]/.test(decoded), 'DOSSIER_ID_INVALID');
  return decoded;
}
function revisionQuery(value) {
  requireValue(typeof value === 'string' && /^[0-9]{1,12}$/.test(value), 'REVISION_INVALID');
  const result = Number(value);
  requireValue(Number.isSafeInteger(result), 'REVISION_INVALID');
  return result;
}
function safeFilename(value) {
  requireValue(typeof value === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,179}$/.test(value),
    'EXPORT_FILENAME_INVALID');
  return value;
}
function providerRegistry(value) {
  requireValue(plain(value), 'EDITION_ADAPTER_PROVIDERS_INVALID');
  for (const [name, provider] of Object.entries(value)) {
    requireValue(/^[a-z][a-z0-9_-]{0,79}$/.test(name) && plain(provider) && typeof provider.read === 'function',
      'EDITION_ADAPTER_PROVIDER_INVALID');
  }
  return value;
}

/** Adapter modules are selected by the local launch command, never by browser input. */
export async function loadEditionAdapters(modulePath) {
  requireValue(typeof modulePath === 'string' && isAbsolute(modulePath) && resolve(modulePath) === modulePath,
    'EDITION_ADAPTER_ABSOLUTE_PATH_REQUIRED');
  const loaded = await import(pathToFileURL(modulePath).href);
  return providerRegistry(loaded.providers);
}

/** Reuses the existing SF88 loopback / fragment-token operator convention. */
export async function startDossierWorkspace({directory, port = 0, providers = {}, openalexWorkspace = null,
  crossrefSource = null, crossrefIdentity = null, documentSource = null, pipelineSource = null, objectStateDirectory = null, clinicalTrialsInputs = null, clinicalTrialsPython = 'python3'} = {}) {
  requireValue(typeof directory === 'string' && isAbsolute(directory) && resolve(directory) === directory,
    'WORKSPACE_ABSOLUTE_PATH_REQUIRED');
  requireValue(Number.isInteger(port) && port >= 0 && port <= 65535, 'WORKSPACE_PORT_INVALID');
  providers = {...providerRegistry(providers)};
  requireValue(documentSource === null || plain(documentSource) && Object.keys(documentSource).every(key =>
    ['buyer','workspaceId','inboxDirectory','runtimeDirectory'].includes(key)), 'DOCUMENT_SOURCE_INVALID');
  requireValue(openalexWorkspace === null || typeof openalexWorkspace?.listEditions === 'function' &&
    typeof openalexWorkspace?.exportFiles === 'function', 'OPENALEX_WORKSPACE_API_REQUIRED');
  const store = await openDossierStore(directory, {providers});
  const workspaceId = researchWorkspaceId(store.directory), instanceId = randomUUID();
  const api = {schema:RESEARCH_WORKSPACE_API,metadata:true,revisionPages:true,streamedPortable:true,sourceBundles:true,sourceInspection:true,
    citationUpdateReview:true,citationReviewRequestLimit:MAX_CITATION_REVIEW_BODY,revisionReports:true,savedCrossrefOperations:crossrefSource!==null,originalObjectInputs:objectStateDirectory!==null};
  await store.list();
  const unstructured = await openUnstructuredWorkspace({dossiers:store,...(documentSource ?? {})});
  if (unstructured.provider) {
    requireValue(!Object.hasOwn(providers, 'unstructured'), 'DOCUMENT_PROVIDER_ALREADY_CONFIGURED');
    providers.unstructured = unstructured.provider;
  }
  let crossref = null;
  if (crossrefSource !== null) {
    const {openCrossrefWorkspace} = await import('./crossref-workspace.mjs');
    crossref = await openCrossrefWorkspace({directory:join(directory,'crossref'),dossiers:store,
      source:crossrefSource,identity:crossrefIdentity});
  }
  let objectInputs=null,pipelines;
  try {
    if(objectStateDirectory!==null)objectInputs=await openResearchObjectSource({
      directory,objectWorkspaceDirectory:objectStateDirectory});
    pipelines=await openUnstructuredPipelineWorkspace({dossiers:store,source:pipelineSource,objectSource:objectInputs});
  } catch(error) {await objectInputs?.close();await crossref?.close();throw error;}
  let clinicalTrials;
  try {
    clinicalTrials = await openClinicalTrialsWorkspace({directory:join(directory,'clinical-trials'),
      dossiers:store,inputs:clinicalTrialsInputs,python:clinicalTrialsPython});
  } catch (error) {unstructured.clear(); await objectInputs?.close(); await pipelines.close(); await crossref?.close(); throw error;}
  const token = randomBytes(32).toString('hex');
  const expectedAuthorization = Buffer.from('Bearer ' + token);
  let origin;
  const server = createServer(async (req, res) => {
    const headers = {
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'no-referrer',
      'Content-Security-Policy': "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'",
    };
    let sourceProjection='full';
    const send = (status, data, type = 'application/json; charset=utf-8', filename) => {
      const content = Buffer.isBuffer(data) ? data : jsonBytes(sourceProjection==='inspection'?inspectResearchResponse(data):data);
      res.writeHead(status, {...headers, 'Content-Type': type, 'Content-Length': content.length,
        ...(filename ? {'Content-Disposition': 'attachment; filename="' + safeFilename(filename) + '"'} : {})});
      res.end(content);
    };
    try {
      requireValue(req.headers.host === new URL(origin).host, 'HOST_REFUSED');
      requireValue(!req.headers.origin || req.headers.origin === origin, 'ORIGIN_REFUSED');
      const url = new URL(req.url, origin);
      const path = url.pathname;
      sourceProjection=url.searchParams.get('sourceProjection')??'full';
      requireValue(['full','inspection'].includes(sourceProjection),'RESEARCH_SOURCE_PROJECTION_INVALID');
      const projection = url.searchParams.get('projection') ?? 'full';
      requireValue(['full','metadata'].includes(projection),'RESEARCH_PROJECTION_INVALID');
      if ((req.method === 'GET' || req.method === 'HEAD') && (path === '/' || Object.hasOwn(TYPES, path.slice(1)))) {
        const name = path === '/' ? 'index.html' : path.slice(1);
        const content = await readFile(join(PUBLIC, name));
        if (req.method === 'HEAD') {
          res.writeHead(200, {...headers, 'Content-Type': TYPES[name], 'Content-Length': content.length}); res.end();
        } else send(200, content, TYPES[name]);
        return;
      }
      const auth = Buffer.from(req.headers.authorization || '');
      requireValue(auth.length === expectedAuthorization.length && timingSafeEqual(auth, expectedAuthorization),
        'AUTH_REQUIRED');
      requireValue(!req.headers['x-research-workspace-id']||req.headers['x-research-workspace-id']===workspaceId,
        'RESEARCH_WORKSPACE_CHANGED');
      requireValue(!req.headers['x-research-instance-id']||req.headers['x-research-instance-id']===instanceId,
        'RESEARCH_INSTANCE_CHANGED');
      if (req.method === 'GET' && path === '/api/status') {
        send(200, {mode:'RESEARCH_DOSSIER_WORKSPACE',api,workspaceId,instanceId,
          dossierCount:(await store.list()).length,providers:Object.keys(providers),
          openalex:{configured:openalexWorkspace!==null},
          crossref:{configured:crossref!==null,identity:crossrefIdentity},
          unstructured:{configured:unstructured.configured,workspaceId:unstructured.workspaceId},
          pipelines:await pipelines.configured(),objects:objectInputs?.source()??{configured:false},
          clinicalTrials:{configured:true,inputFormat:'stellar-forge.clinicaltrials-packet.v1'}});return;
      }
      if (req.method === 'GET' && path === '/api/dossiers') {
        const dossiers=await store.list(),snapshot=digest(canonicalBytes(dossiers));
        const offset=url.searchParams.has('offset')?revisionQuery(url.searchParams.get('offset')):0;
        const limit=url.searchParams.has('limit')?revisionQuery(url.searchParams.get('limit')):30;
        requireValue(offset===0||url.searchParams.get('snapshot')===snapshot,'RESEARCH_INVENTORY_CHANGED');
        const page=researchPage(dossiers,{offset,limit});
        send(200,{workspaceId,snapshot,...page,
          next:page.nextOffset===null?null:{offset:page.nextOffset,limit,snapshot}});return;
      }
      if (req.method === 'GET' && path === '/api/state') {
        send(200, {api,workspaceId,instanceId,dossiers: await store.list(), providers: Object.keys(providers),
          openalex: {configured:openalexWorkspace !== null},
          crossref: {configured:crossref !== null,identity:crossrefIdentity},
          unstructured: {configured:unstructured.configured,workspaceId:unstructured.workspaceId},
          pipelines: await pipelines.configured(),objects:objectInputs?.source()??{configured:false},
          clinicalTrials: {configured:true,inputFormat:'stellar-forge.clinicaltrials-packet.v1'}}); return;
      }
      if (req.method === 'GET' && path === '/api/openalex/editions') {
        requireValue(openalexWorkspace !== null, 'OPENALEX_WORKSPACE_NOT_CONFIGURED');
        const editions = await openalexWorkspace.listEditions();
        requireValue(Array.isArray(editions), 'OPENALEX_EDITION_LIST_INVALID');
        send(200, {editions:editions.filter(edition => edition?.query?.entity === 'works')}); return;
      }
      if (req.method === 'POST' && path === '/api/dossiers') {
        const data = await readJson(req, MAX_CONTROL_BODY);
        send(201, await store.create({...selectedFields(data, ['title', 'description']),projection})); return;
      }
      if (req.method === 'POST' && path === '/api/reopen-stream') {
        const type = (req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
        requireValue(['application/json', 'application/gzip', 'application/x-gzip', 'application/octet-stream'].includes(type),
          'PORTABLE_BODY_REQUIRED');
        const declared = req.headers['content-length'];
        if (declared !== undefined) {
          requireValue(/^[0-9]+$/.test(declared), 'CONTENT_LENGTH_INVALID');
          requireValue(Number(declared) <= 256 * 1024 * 1024, 'UPLOAD_SIZE_LIMIT');
        }
        send(200, await store.reopenStream(req,{projection})); return;
      }
      if (req.method === 'POST' && path === '/api/reopen') {
        const data = await readJson(req, MAX_PORTABLE_BODY);
        requireValue(plain(data.portable), 'PORTABLE_DOSSIER_REQUIRED');
        send(200, await store.reopen(data.portable)); return;
      }
      const match = path.match(/^\/api\/dossiers\/([^/]+)(?:\/(.*))?$/);
      if (!match) {send(404, {error: 'ROUTE_NOT_FOUND'}); return;}
      const id = pathId(match[1]), action = match[2] || '';
      if (req.method === 'GET' && action === '') {
        const options = url.searchParams.has('revision') ? {revision: revisionQuery(url.searchParams.get('revision'))} : {};
        send(200, await (projection==='metadata'?store.getMetadata(id,options):store.get(id, options))); return;
      }
      if (req.method === 'GET' && action === 'metadata') {
        const options=url.searchParams.has('revision')?{revision:revisionQuery(url.searchParams.get('revision'))}:{};
        send(200,researchSummary(await store.getMetadata(id,options)));return;
      }
      const sectionMatch=action.match(/^sections\/([a-z]+)$/);
      if(req.method==='GET'&&sectionMatch){
        const selected=url.searchParams.get('selected');
        requireValue(selected===null||['true','false'].includes(selected),'RESEARCH_SELECTION_INVALID');
        const options={section:sectionMatch[1],
          offset:url.searchParams.has('offset')?revisionQuery(url.searchParams.get('offset')):0,
          limit:url.searchParams.has('limit')?revisionQuery(url.searchParams.get('limit')):30,
          query:url.searchParams.get('query')??''};
        if(url.searchParams.has('revision'))options.revision=revisionQuery(url.searchParams.get('revision'));
        if(url.searchParams.has('questionId'))options.questionId=url.searchParams.get('questionId');
        if(selected!==null)options.selected=selected==='true';
        send(200,await researchSection(store,id,options));return;
      }
      const sourceMatch=action.match(/^retained-editions\/(e_[a-f0-9]{64})\/occurrences\/([^/]+)(?:\/(content|record|file))?$/);
      if(req.method==='GET'&&sourceMatch){
        const options={editionId:sourceMatch[1],key:pathId(sourceMatch[2])};
        if(url.searchParams.has('revision'))options.revision=revisionQuery(url.searchParams.get('revision'));
        if(!sourceMatch[3]){send(200,await inspectRetainedSource(store,id,options));return;}
        const selected={...options,part:sourceMatch[3]};
        if(url.searchParams.has('name'))selected.name=url.searchParams.get('name');
        if(url.searchParams.has('sha256'))selected.expectedSha256=url.searchParams.get('sha256');
        const result=await readRetainedSourceFile(store,id,selected);
        res.setHeader('X-Research-Dossier-Revision',String(result.selection.revision));
        res.setHeader('X-Research-Edition-Id',result.selection.editionId);
        res.setHeader('X-Research-Occurrence-Id',result.selection.occurrenceId);
        res.setHeader('X-Research-Source-Sha256',result.sha256);
        send(200,result.bytes,result.contentType,result.filename);return;
      }
      const retainedMatch=action.match(/^retained-editions\/(e_[a-f0-9]{64})$/);
      if(req.method==='GET'&&retainedMatch){
        const retained=await store.readRetainedEdition(id,retainedMatch[1],url.searchParams.has('revision')?
          {revision:revisionQuery(url.searchParams.get('revision'))}:{});
        res.setHeader('X-Research-Dossier-Revision',String(retained.revision));
        send(200,retained.bytes,'application/json; charset=utf-8',retainedMatch[1]+'.research-source.json');return;
      }
      if (await handleClinicalTrialsRoute({workspace:clinicalTrials,dossierId:id,action,req,url,
        readBody:()=>readJson(req,MAX_CONTROL_BODY),send,projection})) return;
      if (req.method === 'GET' && action === 'unstructured') {
        send(200, await unstructured.list(id, {
          after:url.searchParams.get('after') ?? '',
          limit:url.searchParams.has('limit') ? revisionQuery(url.searchParams.get('limit')) : 20,
        })); return;
      }
      if (req.method === 'GET' && action === 'pipelines') {
        send(200, await pipelines.list(id, {after:url.searchParams.get('after')??'',
          limit:url.searchParams.has('limit')?revisionQuery(url.searchParams.get('limit')):30})); return;
      }
