        result.plan.payload.inputs.length===files.length&&files.every((file,index)=>
          ['filename','contentType','bytes','sha256'].every(key=>result.plan.payload.inputs[index][key]===file[key])),
      'PIPELINE_RETAINED_INPUT_CHANGED');
