  check(native.mode==='ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT'&&typeof native.intentId==='string'&&
    saved?.status==='SAVED'&&saved.bytes===bytes.length&&saved.sha256===digest(bytes),'NATIVE_RESPONSE_MISMATCH');
