    check(saved?.status==='SAVED'&&typeof saved.path==='string','SAVED_BUYER_RESULT_REQUIRED');
    const result=new BuyerResult(plain(record.native)?record:{native:record},{destination:saved.path,maxBytes:MAX_PAGE_BYTES});
